<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../services/userService.php';$pdo=openDatabase();$admin=requireLogin($pdo);requireRole($admin,['Administrator']);$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('Invalid user.');}$target=findUserById($pdo,$id);if(!$target){http_response_code(404);exit('User not found.');}$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);$action=(string)($_POST['action']??'');try{if($action==='role')changeUserRole($pdo,$admin,$id,(string)($_POST['role']??''));elseif($action==='status')changeUserStatus($pdo,$admin,$id,(string)($_POST['status']??''));elseif($action==='delete')$notice=deleteUserSafely($pdo,$admin,$id);else throw new InvalidArgumentException('Unknown action.');$target=findUserById($pdo,$id)?:$target;if($notice==='')$notice='Account updated.';}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Manage Account</h1><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($notice):?><div class="alert alert-info"><?=htmlspecialchars($notice,ENT_QUOTES,'UTF-8')?></div><?php endif;?><p><strong><?=htmlspecialchars($target['full_name'],ENT_QUOTES,'UTF-8')?></strong> — <?=htmlspecialchars($target['email'],ENT_QUOTES,'UTF-8')?></p><p>Current role: <?=htmlspecialchars($target['role'],ENT_QUOTES,'UTF-8')?> | Status: <?=htmlspecialchars($target['status'],ENT_QUOTES,'UTF-8')?></p>
<form method="post" class="mb-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="role"><label class="form-label">New role<select class="form-select" name="role"><?php foreach(['Student','Tutor','Administrator'] as $v):?><option <?=$target['role']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><button class="btn btn-primary">Save Role</button></form>
<form method="post" class="mb-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="status"><label class="form-label">Account status<select class="form-select" name="status"><option <?=$target['status']==='Active'?'selected':''?>>Active</option><option <?=$target['status']==='Inactive'?'selected':''?>>Inactive</option></select></label><button class="btn btn-warning">Update Status</button></form>
<form method="post" onsubmit="return confirm('Request account deletion? The action may be blocked by retention policy.');"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger">Delete Account</button></form><p class="text-muted mt-2">Permanent deletion is currently blocked until the retention policy is approved.</p><a href="/php/admin-users.php">Back to users</a></main><?php require __DIR__.'/../includes/footer.php';?>
